async def register_and_login(client: AsyncClient, username: str, password: str) -> str:
    """
    Register a new user (or login if already exists).
    Returns the JWT access token string.
    """
    reg = await client.post("/auth/register", json={
        "username": username,
        "password": password,
    })

    if reg.status_code == 201:
        # Fresh registration — token is in the response
        return reg.json()["access_token"]

    if reg.status_code == 409:
        # User already exists from a previous test run — just login
        login = await client.post("/auth/login", json={
            "username": username,
            "password": password,
        })
        assert login.status_code == 200, f"Login failed: {login.text}"
        return login.json()["access_token"]

    raise AssertionError(f"Unexpected register response {reg.status_code}: {reg.text}")


async def create_project(client: AsyncClient, headers: dict, name: str) -> str:
    """Create a project and return its project_id."""
    resp = await client.post(
        "/projects",
        json={"name": name, "description": f"Test project: {name}"},
        headers=headers,
    )
    assert resp.status_code == 201, f"Project creation failed: {resp.text}"
    return resp.json()["id"]


async def poll_until_ready(
    client: AsyncClient,
    headers: dict,
    project_id: str,
    document_id: str,
    max_attempts: int = 20,
    delay_seconds: float = 0.3,
) -> dict:
    """
    Poll GET /projects/{project_id}/documents/{document_id}
    until status is 'ready' or 'failed', or max_attempts is reached.
    Returns the final document status response dict.
    """
    for attempt in range(max_attempts):
        resp = await client.get(
            f"/projects/{project_id}/documents/{document_id}",
            headers=headers,
        )
        assert resp.status_code == 200, f"Status poll failed: {resp.text}"
        data = resp.json()

        if data["status"] in ("ready", "failed"):
            return data

        # Still pending/parsing — wait a bit before retrying
        await asyncio.sleep(delay_seconds)

    raise TimeoutError(
        f"Document {document_id} did not reach ready/failed after "
        f"{max_attempts} attempts ({max_attempts * delay_seconds}s)"
    )


