class TestDocumentUpload:
    """Tests for POST /projects/{project_id}/documents"""

    @pytest.mark.asyncio
    async def test_upload_txt_returns_202(self, client, user_a_headers, project_a):
        """
        Uploading a valid TXT file should return 202 Accepted with a document_id.
        The parse job runs in the background so we don't wait for 'ready' here.
        """
        resp = await client.post(
            f"/projects/{project_a}/documents",
            files={"file": ("requirements.txt", TXT_CONTENT, "text/plain")},
            params={"kind": "BRD"},
            headers=user_a_headers,
        )

        assert resp.status_code == 202, f"Expected 202, got {resp.status_code}: {resp.text}"
        data = resp.json()

        # Must return a document_id
        assert "document_id" in data
        assert len(data["document_id"]) == 36  # UUID format

        # Filename must match what we sent
        assert data["filename"] == "requirements.txt"

        # Status must be one of the valid pending states
        assert data["status"] in ("pending", "parsing", "ready")

        # Response must include a human-readable message
        assert "message" in data

    @pytest.mark.asyncio
    async def test_upload_markdown_returns_202(self, client, user_a_headers, project_a):
        """Uploading a valid Markdown file should return 202."""
        resp = await client.post(
            f"/projects/{project_a}/documents",
            files={"file": ("prd.md", MD_CONTENT, "text/markdown")},
            params={"kind": "PRD"},
            headers=user_a_headers,
        )

        assert resp.status_code == 202
        data = resp.json()
        assert "document_id" in data
        assert data["filename"] == "prd.md"

    @pytest.mark.asyncio
    async def test_upload_txt_with_kind_trd(self, client, user_a_headers, project_a):
        """
        The 'kind' query parameter should be stored and returned correctly.
        Tests that BRD / PRD / TRD / other all work.
        """
        resp = await client.post(
            f"/projects/{project_a}/documents",
            files={"file": ("tech_spec.txt", TXT_CONTENT, "text/plain")},
            params={"kind": "TRD"},
            headers=user_a_headers,
        )

        assert resp.status_code == 202

        # Poll until ready and verify the kind was stored
        doc_id = resp.json()["document_id"]
        final = await poll_until_ready(client, user_a_headers, project_a, doc_id)
        assert final["kind"] == "TRD"

    @pytest.mark.asyncio
    async def test_upload_default_kind_is_other(self, client, user_a_headers, project_a):
        """
        If no 'kind' param is passed, it should default to 'other'.
        """
        resp = await client.post(
            f"/projects/{project_a}/documents",
            files={"file": ("misc.txt", SHORT_TXT, "text/plain")},
            # No 'kind' param
            headers=user_a_headers,
        )

        assert resp.status_code == 202
        doc_id = resp.json()["document_id"]
        final = await poll_until_ready(client, user_a_headers, project_a, doc_id)
        assert final["kind"] == "other"

    @pytest.mark.asyncio
    async def test_uploaded_document_appears_in_list(self, client, user_a_headers, project_a):
        """
        After uploading, the document should appear in
        GET /projects/{project_id}/documents.
        """
        # Upload a fresh document
        resp = await client.post(
            f"/projects/{project_a}/documents",
            files={"file": ("list_test.txt", TXT_CONTENT, "text/plain")},
            headers=user_a_headers,
        )
        assert resp.status_code == 202
        doc_id = resp.json()["document_id"]

        # Fetch the list
        list_resp = await client.get(
            f"/projects/{project_a}/documents",
            headers=user_a_headers,
        )
        assert list_resp.status_code == 200
        data = list_resp.json()

        # The document must appear in the list
        assert "items" in data
        assert "total" in data
