class TestDocumentUploadValidation:
    """Tests for error cases in POST /projects/{project_id}/documents"""

    @pytest.mark.asyncio
    async def test_unsupported_mime_returns_415(self, client, user_a_headers, project_a):
        """
        Uploading an unsupported file type (PNG) must return 415
        with a structured error body.
        """
        resp = await client.post(
            f"/projects/{project_a}/documents",
            files={"file": ("image.png", b"\x89PNG\r\n\x1a\n", "image/png")},
            headers=user_a_headers,
        )

        assert resp.status_code == 415
        error = resp.json()["detail"]
        assert error["code"] == "UNSUPPORTED_MIME_TYPE"
        assert "message" in error
        # The error should tell the user what IS supported
        assert "details" in error

    @pytest.mark.asyncio
    async def test_unsupported_mime_csv_returns_415(self, client, user_a_headers, project_a):
        """CSV is not in our supported list — must return 415."""
        resp = await client.post(
            f"/projects/{project_a}/documents",
            files={"file": ("data.csv", b"col1,col2\nval1,val2", "text/csv")},
            headers=user_a_headers,
        )
        assert resp.status_code == 415

    @pytest.mark.asyncio
    async def test_oversized_file_returns_413(self, client, user_a_headers, project_a):
        """
        Files larger than 50MB must be rejected with 413.
        We simulate this with 51MB of fake content.
        """
        # 51MB of repeated bytes — well above the 50MB limit
        large_content = b"x" * (51 * 1024 * 1024)

        resp = await client.post(
            f"/projects/{project_a}/documents",
            files={"file": ("huge.txt", large_content, "text/plain")},
            headers=user_a_headers,
        )

        assert resp.status_code == 413
        error = resp.json()["detail"]
        assert error["code"] == "FILE_TOO_LARGE"
        assert "message" in error

    @pytest.mark.asyncio
    async def test_upload_to_nonexistent_project_returns_404(
        self, client, user_a_headers
    ):
        """
        Uploading to a project_id that doesn't exist must return 404.
        Must never return 403 (to avoid leaking existence).
        """
        fake_project_id = "00000000-0000-0000-0000-000000000000"

        resp = await client.post(
            f"/projects/{fake_project_id}/documents",
            files={"file": ("test.txt", SHORT_TXT, "text/plain")},
            headers=user_a_headers,
        )

        assert resp.status_code == 404

    @pytest.mark.asyncio
    async def test_upload_without_auth_returns_403(self, client, project_a):
        """
        Requests without a Bearer token must be rejected.
        FastAPI's HTTPBearer returns 403 when the Authorization header is missing.
        """
        resp = await client.post(
            f"/projects/{project_a}/documents",
            files={"file": ("test.txt", SHORT_TXT, "text/plain")},
            # No Authorization header
        )

        assert resp.status_code == 403

    @pytest.mark.asyncio
    async def test_upload_with_invalid_token_returns_401(self, client, project_a):
        """
        A malformed or expired JWT must be rejected with 401.
        """
        resp = await client.post(
            f"/projects/{project_a}/documents",
            files={"file": ("test.txt", SHORT_TXT, "text/plain")},
            headers={"Authorization": "Bearer this.is.not.a.valid.token"},
        )

        assert resp.status_code == 401


