class TestDocumentIdempotency:
    """Tests for duplicate upload detection (same content hash → same document_id)."""

    @pytest.mark.asyncio
    async def test_duplicate_upload_returns_same_document_id(
        self, client, user_a_headers, project_a
    ):
        """
        Uploading the exact same file bytes twice to the same project
        must return the same document_id both times.
        No duplicate rows should be created.
        """
        # First upload
        resp1 = await client.post(
            f"/projects/{project_a}/documents",
            files={"file": ("dup_test.txt", DUPLICATE_CONTENT, "text/plain")},
            headers=user_a_headers,
        )
        assert resp1.status_code in (200, 202)
        doc_id_1 = resp1.json()["document_id"]

        # Second upload — identical content
        resp2 = await client.post(
            f"/projects/{project_a}/documents",
            files={"file": ("dup_test_renamed.txt", DUPLICATE_CONTENT, "text/plain")},
            headers=user_a_headers,
        )
        assert resp2.status_code in (200, 202)
        doc_id_2 = resp2.json()["document_id"]

        # Both must return the same document_id
        assert doc_id_1 == doc_id_2, (
            f"Expected same document_id for duplicate upload, "
            f"got {doc_id_1} and {doc_id_2}"
        )

    @pytest.mark.asyncio
    async def test_different_content_creates_different_document(
        self, client, user_a_headers, project_a
    ):
        """
        Two files with different content must get different document_ids.
        This verifies the hash comparison works correctly.
        """
        content_a = b"This is document content version ALPHA unique string 111."
        content_b = b"This is document content version BETA unique string 222."

        resp_a = await client.post(
            f"/projects/{project_a}/documents",
            files={"file": ("doc_a.txt", content_a, "text/plain")},
            headers=user_a_headers,
        )
        resp_b = await client.post(
            f"/projects/{project_a}/documents",
            files={"file": ("doc_b.txt", content_b, "text/plain")},
            headers=user_a_headers,
        )

        assert resp_a.status_code in (200, 202)
        assert resp_b.status_code in (200, 202)

        doc_id_a = resp_a.json()["document_id"]
        doc_id_b = resp_b.json()["document_id"]

        assert doc_id_a != doc_id_b, "Different content must produce different document IDs"

    @pytest.mark.asyncio
    async def test_same_content_different_projects_creates_separate_documents(
        self, client, user_a_headers, user_b_headers, project_a, project_b
    ):
        """
        The same file content uploaded to two different projects must create
        two separate document rows (deduplication is per-project, not global).
        """
        shared_content = b"Shared content uploaded to two different projects for isolation test."

        resp_a = await client.post(
            f"/projects/{project_a}/documents",
            files={"file": ("shared.txt", shared_content, "text/plain")},
            headers=user_a_headers,
        )
        resp_b = await client.post(
            f"/projects/{project_b}/documents",
            files={"file": ("shared.txt", shared_content, "text/plain")},
            headers=user_b_headers,
        )

        assert resp_a.status_code in (200, 202)
        assert resp_b.status_code in (200, 202)

        doc_id_a = resp_a.json()["document_id"]
        doc_id_b = resp_b.json()["document_id"]

        # Must be separate documents — different projects, different rows
        assert doc_id_a != doc_id_b


