class TestDocumentStatus:
    """Tests for GET /projects/{project_id}/documents/{document_id}"""

    @pytest.mark.asyncio
    async def test_status_reaches_ready_after_parse(
        self, client, user_a_headers, project_a
    ):
        """
        After upload, polling should eventually return status='ready'
        with section_count > 0 and chunk_count > 0.
        """
        # Upload a document with clear sections
        resp = await client.post(
            f"/projects/{project_a}/documents",
            files={"file": ("poll_test.md", MD_CONTENT, "text/markdown")},
            params={"kind": "PRD"},
            headers=user_a_headers,
        )
        assert resp.status_code == 202
        doc_id = resp.json()["document_id"]

        # Poll until ready
        final = await poll_until_ready(client, user_a_headers, project_a, doc_id)

        assert final["status"] == "ready", (
            f"Expected status=ready, got {final['status']}. "
            f"Error: {final.get('error_message')}"
        )
        assert final["chunk_count"] > 0, "Ready document must have at least one chunk"
        assert final["section_count"] > 0, "Ready document must have at least one section"

    @pytest.mark.asyncio
    async def test_status_has_correct_metadata(
        self, client, user_a_headers, project_a
    ):
        """
        The status response must include all expected fields:
        id, project_id, filename, extension, mime_type, file_size, kind,
        status, section_count, chunk_count, created_at, updated_at.
        """
        resp = await client.post(
            f"/projects/{project_a}/documents",
            files={"file": ("metadata_test.txt", TXT_CONTENT, "text/plain")},
            params={"kind": "BRD"},
            headers=user_a_headers,
        )
        assert resp.status_code == 202
        doc_id = resp.json()["document_id"]

        # Wait for parse to complete
        final = await poll_until_ready(client, user_a_headers, project_a, doc_id)

        # Verify all expected fields are present and correct
        assert final["id"] == doc_id
        assert final["project_id"] == project_a
        assert final["filename"] == "metadata_test.txt"
        assert final["extension"] == "txt"
        assert final["mime_type"] == "text/plain"
        assert final["file_size"] == len(TXT_CONTENT)
        assert final["kind"] == "BRD"
        assert final["status"] == "ready"
        assert final["chunk_count"] > 0
        assert final["section_count"] > 0
        assert "created_at" in final
        assert "updated_at" in final
        assert final["error_message"] is None

    @pytest.mark.asyncio
    async def test_get_status_for_nonexistent_document_returns_404(
        self, client, user_a_headers, project_a
    ):
        """
        Polling a document_id that doesn't exist in this project must return 404.
        """
        fake_doc_id = "00000000-0000-0000-0000-000000000000"

        resp = await client.get(
            f"/projects/{project_a}/documents/{fake_doc_id}",
            headers=user_a_headers,
        )

        assert resp.status_code == 404
        assert resp.json()["detail"]["code"] == "DOCUMENT_NOT_FOUND"

    @pytest.mark.asyncio
    async def test_get_status_without_auth_returns_403(self, client, project_a):
        """Status endpoint must reject unauthenticated requests."""
        resp = await client.get(
            f"/projects/{project_a}/documents/some-doc-id",
            # No auth header
        )
        assert resp.status_code == 403


