class TestCrossProjectIsolation:
    """
    Tests that documents from one project are NOT accessible from another project.
    This is a core security requirement — cross-project leakage is a defect.
    """

    @pytest.mark.asyncio
    async def test_document_not_visible_across_projects(
        self, client, user_a_headers, user_b_headers, project_a, project_b
    ):
        """
        A document uploaded to Project A must NOT be accessible via Project B's URL,
        even if both users are authenticated.
        Returns 404 (not 403) to avoid leaking existence.
        """
        # User A uploads a document to Project A
        resp = await client.post(
            f"/projects/{project_a}/documents",
            files={"file": ("project_a_doc.txt", TXT_CONTENT, "text/plain")},
            headers=user_a_headers,
        )
        assert resp.status_code == 202
        doc_id_from_project_a = resp.json()["document_id"]

        # User B tries to access Project A's document via Project B's URL
        cross_resp = await client.get(
            f"/projects/{project_b}/documents/{doc_id_from_project_a}",
            headers=user_b_headers,
        )

        # Must return 404 — not 403, not 200
        assert cross_resp.status_code == 404, (
            f"Cross-project document access must return 404, "
            f"got {cross_resp.status_code}"
        )

    @pytest.mark.asyncio
    async def test_document_list_is_scoped_to_project(
        self, client, user_a_headers, user_b_headers, project_a, project_b
    ):
        """
        GET /projects/{project_id}/documents must only return documents
        that belong to that specific project.
        """
        # Upload unique document to project A
        await client.post(
            f"/projects/{project_a}/documents",
            files={"file": ("only_in_a.txt", b"Only in project A - unique content xyz123", "text/plain")},
            headers=user_a_headers,
        )

        # Upload different document to project B
        await client.post(
            f"/projects/{project_b}/documents",
            files={"file": ("only_in_b.txt", b"Only in project B - unique content abc456", "text/plain")},
            headers=user_b_headers,
        )

        # Get document list for project A
        list_a = await client.get(
            f"/projects/{project_a}/documents",
            headers=user_a_headers,
        )
        assert list_a.status_code == 200

        # Get document list for project B
        list_b = await client.get(
            f"/projects/{project_b}/documents",
            headers=user_b_headers,
        )
        assert list_b.status_code == 200

        ids_in_a = {item["id"] for item in list_a.json()["items"]}
        ids_in_b = {item["id"] for item in list_b.json()["items"]}

        # The two lists must not overlap
        overlap = ids_in_a & ids_in_b
        assert len(overlap) == 0, (
            f"Projects share document IDs — cross-project leakage detected: {overlap}"
        )

    @pytest.mark.asyncio
    async def test_user_cannot_access_another_users_project_documents(
        self, client, user_a_headers, user_b_headers, project_a
    ):
        """
        User B must not be able to list documents in User A's project.
        Returns 404 because User B cannot see Project A at all.
        """
        # User B tries to list documents in User A's project
        resp = await client.get(
            f"/projects/{project_a}/documents",
            headers=user_b_headers,
        )

        # 404 because the project doesn't exist for User B's scope
        assert resp.status_code == 404


