class TestDocumentSections:
    """Tests for GET /projects/{project_id}/documents/{document_id}/sections"""

    @pytest.mark.asyncio
    async def test_sections_returns_structured_outline(
        self, client, user_a_headers, project_a
    ):
        """
        After a document is parsed, the sections endpoint must return a structured
        outline with section_id, section_title, chunk_index, page, and text_preview.
        """
        # Upload a Markdown file — it has explicit heading structure
        resp = await client.post(
            f"/projects/{project_a}/documents",
            files={"file": ("sections_test.md", MD_CONTENT, "text/markdown")},
            headers=user_a_headers,
        )
        assert resp.status_code == 202
        doc_id = resp.json()["document_id"]

        # Wait for parse
        final = await poll_until_ready(client, user_a_headers, project_a, doc_id)
        assert final["status"] == "ready"

        # Fetch sections
        sections_resp = await client.get(
            f"/projects/{project_a}/documents/{doc_id}/sections",
            headers=user_a_headers,
        )
        assert sections_resp.status_code == 200
        data = sections_resp.json()

        # Verify response structure
        assert data["document_id"] == doc_id
        assert "filename" in data
        assert "sections" in data
        assert "total_sections" in data

        # Must have at least one section
        assert data["total_sections"] > 0
        assert len(data["sections"]) == data["total_sections"]

        # Each section must have all required fields
        for section in data["sections"]:
            assert "section_id" in section, "Each section must have a section_id"
            assert "section_title" in section, "Each section must have a section_title"
            assert "chunk_index" in section, "Each section must have a chunk_index"
            assert "page" in section, "Each section must have a page number"
            assert "text_preview" in section, "Each section must have a text_preview"

            # text_preview must be non-empty
            assert len(section["text_preview"]) > 0

            # text_preview must be at most 203 chars (200 + "...")
            assert len(section["text_preview"]) <= 203

    @pytest.mark.asyncio
    async def test_sections_for_unparsed_document_returns_409(
        self, client, user_a_headers, project_a
    ):
        """
        Requesting sections for a document that is still parsing must return 409
        (Conflict — document not ready).
        We test this by checking the behavior when status != ready.
        """
        # Upload a document — it starts in 'pending' state
        resp = await client.post(
            f"/projects/{project_a}/documents",
            files={"file": ("pending_sections.txt", TXT_CONTENT, "text/plain")},
            headers=user_a_headers,
        )
        assert resp.status_code == 202
        doc_id = resp.json()["document_id"]

        # Immediately try to get sections (before parse completes)
        # If the parse is instant, this might pass — we check both cases
        sections_resp = await client.get(
            f"/projects/{project_a}/documents/{doc_id}/sections",
            headers=user_a_headers,
        )

        # Either 200 (if parsed instantly) or 409 (if still pending/parsing)
        assert sections_resp.status_code in (200, 409), (
            f"Unexpected status code: {sections_resp.status_code}"
        )

        if sections_resp.status_code == 409:
            error = sections_resp.json()["detail"]
            assert error["code"] == "DOCUMENT_NOT_READY"

    @pytest.mark.asyncio
    async def test_sections_for_nonexistent_document_returns_404(
        self, client, user_a_headers, project_a
    ):
        """
        Requesting sections for a document_id that doesn't exist must return 404.
        """
        resp = await client.get(
            f"/projects/{project_a}/documents/nonexistent-doc-id/sections",
            headers=user_a_headers,
        )
        assert resp.status_code == 404

    @pytest.mark.asyncio
    async def test_sections_not_accessible_across_projects(
        self, client, user_a_headers, user_b_headers, project_a, project_b
    ):
        """
        Sections endpoint must respect project scope.
        User B cannot access sections of a document in User A's project.
        """
        # Upload to project A
        resp = await client.post(
            f"/projects/{project_a}/documents",
            files={"file": ("scope_test.txt", TXT_CONTENT, "text/plain")},
            headers=user_a_headers,
        )
        assert resp.status_code == 202
        doc_id = resp.json()["document_id"]

        # Wait until ready
        await poll_until_ready(client, user_a_headers, project_a, doc_id)

        # User B tries to access via project B URL — must return 404
        cross_resp = await client.get(
            f"/projects/{project_b}/documents/{doc_id}/sections",
            headers=user_b_headers,
        )
        assert cross_resp.status_code == 404


