# 7. Document List                                                      #
# ------------------------------------------------------------------ #

class TestDocumentList:
    """Tests for GET /projects/{project_id}/documents"""

    @pytest.mark.asyncio
    async def test_list_returns_all_documents(
        self, client, user_a_headers, project_a
    ):
        """
        After uploading multiple documents, the list endpoint must return all of them.
        Response must include 'items' and 'total' fields.
        """
        # Upload 2 distinct documents
        content_1 = b"First document for list test - unique marker AAAA."
        content_2 = b"Second document for list test - unique marker BBBB."

        await client.post(
            f"/projects/{project_a}/documents",
            files={"file": ("list_doc_1.txt", content_1, "text/plain")},
            headers=user_a_headers,
        )
        await client.post(
            f"/projects/{project_a}/documents",
            files={"file": ("list_doc_2.txt", content_2, "text/plain")},
            headers=user_a_headers,
        )

        # Fetch the list
        resp = await client.get(
            f"/projects/{project_a}/documents",
            headers=user_a_headers,
        )
        assert resp.status_code == 200
        data = resp.json()

        # Must have proper structure
        assert "items" in data
        assert "total" in data
        assert isinstance(data["items"], list)
        assert data["total"] >= 2  # at least our 2 uploads (plus any from previous tests)

        # Each item must have the required fields
        for item in data["items"]:
            assert "id" in item
            assert "filename" in item
            assert "status" in item
            assert "kind" in item
            assert "created_at" in item

    @pytest.mark.asyncio
    async def test_list_empty_project_returns_empty(
        self, client, user_a_headers
    ):
        """
        A brand new project with no uploads must return an empty list.
        """
        # Create a fresh project with no documents
        empty_project = await create_project(
            client, user_a_headers, "Empty Document Project"
        )

        resp = await client.get(
            f"/projects/{empty_project}/documents",
            headers=user_a_headers,
        )
        assert resp.status_code == 200
        data = resp.json()
        assert data["total"] == 0
        assert data["items"] == []

    @pytest.mark.asyncio
    async def test_list_without_auth_returns_403(self, client, project_a):
        """Document list must reject unauthenticated requests."""
        resp = await client.get(f"/projects/{project_a}/documents")
        assert resp.status_code == 403


# ------------------------------------------------------------------ #
# 8. Parser Unit Tests (no HTTP — direct function calls)              #
# ------------------------------------------------------------------ #

class TestParser:
    """
    Unit tests for individual parser functions.
    These call the parser functions directly without going through the API.
    No network calls, no DB — pure logic tests.
    """

    def test_parse_txt_returns_chunks(self):
        """TXT parser must return at least one chunk for non-empty input."""
        from app.documents.parser import parse_txt

        chunks = parse_txt(TXT_CONTENT)

        assert len(chunks) > 0
        for chunk in chunks:
            # Each chunk must have all required fields
            assert "section_id" in chunk
            assert "text" in chunk
            assert "section_title" in chunk
            assert "page" in chunk
            assert "chunk_index" in chunk
            # Text must be non-empty
            assert len(chunk["text"].strip()) > 0

    def test_parse_markdown_detects_headings(self):
        """
        Markdown parser must use headings as section boundaries.
        Our test MD has headings like '# Product Requirements Document',
        '## Overview', etc. — each should produce a separate section.
        """
        from app.documents.parser import parse_markdown

        chunks = parse_markdown(MD_CONTENT)

        assert len(chunks) > 0

        # At least one chunk should have a non-empty section_title
        titles = [c["section_title"] for c in chunks if c["section_title"]]
        assert len(titles) > 0, "Markdown parser must extract heading-based section titles"

    def test_parse_txt_empty_input_returns_empty(self):
        """An empty file should produce zero chunks."""
        from app.documents.parser import parse_txt

        chunks = parse_txt(b"")
        assert chunks == []

    def test_parse_txt_whitespace_only_returns_empty(self):
        """A file with only whitespace should produce zero chunks."""
        from app.documents.parser import parse_txt

        chunks = parse_txt(b"   \n\n\t\n   ")
        assert chunks == []

    def test_chunk_indices_are_sequential(self):
        """
        chunk_index values across all chunks must be sequential (0, 1, 2, ...).
        This is important for ordering chunks when reconstructing a document.
        """
        from app.documents.parser import parse_markdown

        chunks = parse_markdown(MD_CONTENT)
        indices = [c["chunk_index"] for c in chunks]

        assert indices == list(range(len(indices))), (
            f"chunk_index values must be sequential, got: {indices}"
        )

    def test_parse_document_dispatcher_txt(self):
        """parse_document() dispatcher must route 'txt' to parse_txt."""
        from app.documents.parser import parse_document

        chunks = parse_document(SHORT_TXT, "txt")
        assert isinstance(chunks, list)
        assert len(chunks) > 0

    def test_parse_document_dispatcher_md(self):
        """parse_document() dispatcher must route 'md' to parse_markdown."""
        from app.documents.parser import parse_document

        chunks = parse_document(MD_CONTENT, "md")
        assert isinstance(chunks, list)
        assert len(chunks) > 0

    def test_parse_document_unsupported_extension_raises(self):
        """parse_document() must raise ValueError for unsupported extensions."""
        from app.documents.parser import parse_document

        with pytest.raises(ValueError, match="Unsupported file extension"):
            parse_document(b"some content", "xyz")

    def test_get_extension_from_mime_known_types(self):
        """MIME type to extension mapping must work for all supported types."""
        from app.documents.parser import get_extension_from_mime

        assert get_extension_from_mime("application/pdf") == "pdf"
        assert get_extension_from_mime("application/vnd.openxmlformats-officedocument.wordprocessingml.document") == "docx"
        assert get_extension_from_mime("application/vnd.openxmlformats-officedocument.presentationml.presentation") == "pptx"
        assert get_extension_from_mime("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet") == "xlsx"
        assert get_extension_from_mime("text/markdown") == "md"
        assert get_extension_from_mime("text/x-markdown") == "md"
        assert get_extension_from_mime("text/plain") == "txt"

    def test_get_extension_from_mime_unknown_returns_none(self):
        """Unsupported MIME types must return None."""
        from app.documents.parser import get_extension_from_mime

        assert get_extension_from_mime("image/png") is None
        assert get_extension_from_mime("text/csv") is None
        assert get_extension_from_mime("application/json") is None
        assert get_extension_from_mime("") is None

    def test_split_text_respects_chunk_size(self):
        """split_text_into_chunks must not produce chunks larger than chunk_size."""
        from app.documents.parser import split_text_into_chunks

        long_text = "This is a sentence. " * 200  # 4000 characters
        chunks = split_text_into_chunks(long_text, chunk_size=500, chunk_overlap=50)

        for chunk in chunks:
            # Allow a small buffer for sentence-boundary detection
            assert len(chunk) <= 600, (
                f"Chunk exceeds expected size limit: {len(chunk)} chars"
            )

    def test_split_text_produces_overlap(self):
        """
        With overlap enabled, adjacent chunks should share some content.
        We verify this by checking that the total character count across
        all chunks is greater than the original text length.
        """
        from app.documents.parser import split_text_into_chunks

        text = "Word " * 500  # 2500 characters
        chunks_with_overlap = split_text_into_chunks(text, chunk_size=200, chunk_overlap=50)
        chunks_no_overlap   = split_text_into_chunks(text, chunk_size=200, chunk_overlap=0)

        total_with = sum(len(c) for c in chunks_with_overlap)
        total_without = sum(len(c) for c in chunks_no_overlap)

        # With overlap, total characters should be more
        assert total_with >= total_without, (
            "Overlapping chunks should have more total content than non-overlapping"
        )
